urlset:
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink is containing(pat="/musings/")
    and not sitemap_entry.permalink is ending_with(pat="/musings/") %}
{%- continue %}
{%- endif %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endfor %}
